const browser = await pw.chromium.launch({ headless: !args.headed });   // headed is opt-in (needed for first sign-in)
const context = await browser.newContext({
  // Inject saved cookies/tokens if we have them; otherwise a clean context.
  ...(fs.existsSync(AUTH_FILE) ? { storageState: AUTH_FILE } : {}),
  viewport: { width: 1920, height: 1080 },
});
const page = await context.newPage();

// networkidle can legitimately time out on an app that background-polls; swallow
// it so the next line can inspect the ACTUAL landing URL instead of crashing.
await page.goto(baseUrl + '/home', { waitUntil: 'networkidle', timeout: 60000 }).catch(() => {});

// Detect an SSO bounce by URL. If redirected, wait for the human to finish login...
if (page.url().includes('login.microsoftonline') || page.url().includes('login.live.com')) {
  console.log('Waiting for manual login (up to 3 min)...');
  await page.waitForURL(`${baseUrl}/**`, { timeout: 180000 });   // return-to-app == login done
  await context.storageState({ path: AUTH_FILE });   // persist so future runs skip sign-in
}

const toolsItem = page.locator('li[data-menuitem][aria-label="Tools"]').first();
await toolsItem.click();

const modifiersItem = page.locator('li:has-text("Modifiers")').first();
await modifiersItem.click();

// Pin the container by a stable test hook, then READ its current value first.
const funcCallContainer = page.locator('.test-FunctionCallModifiers').first();
const currentVal = await funcCallContainer.locator('.k-input-value-text').textContent().catch(() => '');

// Only toggle if it isn't already 'Yes' — re-runs don't needlessly re-flip it.
// trim().toLowerCase() defends against stray whitespace/casing in the label.
if (currentVal?.trim().toLowerCase() !== 'yes') {
  // Two-selector fallbacks so a component-library class rename doesn't break the click.
  const caretBtn = funcCallContainer.locator('.k-input-button, button[aria-label="Select"]').first();
  await caretBtn.click();
  const yesOption = page.locator('.k-list-item:has-text("Yes"), li:has-text("Yes")').first();
  await yesOption.click();
}

const submitBtn = page.locator('.test-SubmitButton').first();
await submitBtn.click({ force: true });   // force: bypass actionability so an overlay/animation can't block it

async function waitForEditable(page: Page, textarea: any, baseUrl: string, timeoutMs = 30000): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    // Pessimistic .catch defaults: a transient DOM detach reads as 'still locked'
    // so we keep waiting rather than falsely declaring the box ready.
    const ro = await textarea.getAttribute('aria-readonly').catch(() => 'true');
    const readonlyAttr = await textarea.getAttribute('readonly').catch(() => null);
    // Require BOTH signals clear — the app can toggle either independently.
    if (ro !== 'true' && readonlyAttr === null) return true;
    await page.waitForTimeout(500);
  }
  // Escalating recovery: jolt focus with a forced click...
  await textarea.click({ force: true });
  await page.waitForTimeout(2000);
  const ro2 = await textarea.getAttribute('aria-readonly').catch(() => 'true');
  if (ro2 !== 'true') return true;
  // ...then a full reload as a last resort.
  await page.goto(baseUrl + '/home', { waitUntil: 'networkidle', timeout: 30000 }).catch(() => {});
  // ...retries once more before giving up
  return false;   // report a genuinely stuck box rather than hang forever
}

async function waitForResponseComplete(page: Page, timeoutMs = 300000): Promise<string> {
  const responseLocator = page.locator('div.textMessageOutput').last();   // .last(): the newest answer
  await responseLocator.waitFor({ state: 'attached', timeout: 60000 }).catch(() => {});

  let prevHTML = '';
  let stableCount = 0;
  const deadline = Date.now() + timeoutMs;   // 5-min hard cap so a never-ending answer can't hang the batch

  while (Date.now() < deadline) {
    const curHTML = await responseLocator.innerHTML({ timeout: 5000 }).catch(() => '');   // '' on transient error
    // length>0 guards against an empty read (element momentarily detached) being
    // mistaken for a stable answer. Compare HTML byte-for-byte, not text/length,
    // so a late citation chip still resets stability.
    if (curHTML.length > 0 && curHTML === prevHTML) {
      stableCount++;
      // Need 30 consecutive stable checks (30 x 2s = 60s of no change)
      if (stableCount >= 30) break;
    } else {
      stableCount = 0;   // ANY change restarts the 60s window — it must be clean end-to-end
    }
    prevHTML = curHTML;
    await page.waitForTimeout(2000);
  }
  return await responseLocator.textContent({ timeout: 5000 }).catch(() => '');
}

// Trace presence — isVisible().catch(false) so a missing panel logs 'not found', not a throw.
const funcCallExpander = page.locator('.k-expander-title:has-text("FUNCTION CALLS")').first();
if (await funcCallExpander.isVisible({ timeout: 10000 }).catch(() => false)) {
  funcCallInfo = ((await funcCallExpander.textContent().catch(() => '')) || '').trim();
}

// Capture the conversation title from the header (same crash-safe pattern).
const h2Locator = page.locator('h2.text-primary.text-truncate').first();
if (await h2Locator.isVisible({ timeout: 5000 }).catch(() => false)) {
  convTitle = (await h2Locator.textContent({ timeout: 3000 }).catch(() => '')).trim();
}

await clickAppHome(page, baseUrl);

// Persistence check: save-to-history is async, so poll the saved list up to 45s.
// Match on the first 30 chars, lowercased — loose on purpose, since the panel
// may truncate/reformat the title vs. the header h2.
const titleSnippet = convTitle.slice(0, 30).toLowerCase();
const panelDeadline = Date.now() + 45000;
while (Date.now() < panelDeadline) {
  // Re-query every iteration so newly-arrived list entries are seen.
  const panelItems = page.locator('.main-conversations-panel .conversation-item-btn .k-button-text span');
  const count = await panelItems.count().catch(() => 0);
  for (let b = 0; b < count; b++) {
    const itemText = await panelItems.nth(b).textContent({ timeout: 1000 }).catch(() => '');
    if (itemText.toLowerCase().includes(titleSnippet)) { foundInPanel = true; break; }
  }
  if (foundInPanel) break;
  await page.waitForTimeout(2000);
}
// 45s with no hit -> foundInPanel stays false: the reportable save-bug signal.

const outDir = path.resolve(__dirname, '..', 'outputs', 'reports', 'function-call-shares');
fs.mkdirSync(outDir, { recursive: true });   // create the full report path idempotently
// Replace ':' and '.' (illegal/awkward in filenames), keep second precision;
// env tag keeps a dev run from clobbering a qa run's report.
const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const outPath = path.join(outDir, `FuncCallShare_${args.env}_${ts}.json`);
fs.writeFileSync(outPath, JSON.stringify({
  env: args.env,
  timestamp: new Date().toISOString(),
  results,   // verbatim per-prompt outcomes — a missing-trace/not-found row is preserved to chase
}, null, 2));
